"""Self-contained offline review page. No upload, external script, or browser service."""
import json
from pathlib import Path

def review_page(path, annotations, codebook, criteria, reference, audit):
    payload=dict(rows=annotations.fillna('').to_dict('records'),codebook=codebook,criteria=criteria,reference=reference,hash=audit['workbook_sha256'])
    data=json.dumps(payload,ensure_ascii=False).replace('</','<\\/')
    Path(path).write_text(TEMPLATE.replace('__DATA__',data),encoding='utf-8')

TEMPLATE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>STSELab explanation review</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#edf2f6;color:#17324d;font:15px/1.5 system-ui,sans-serif}header{background:#17324d;color:white;padding:20px 28px}h1{font-size:23px;margin:0 0 4px}h2{font-size:18px}h3{font-size:15px}.bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:14px 28px;background:white;border-bottom:1px solid #cdd8e2}button,select,input,textarea{font:inherit;border:1px solid #b5c5d2;border-radius:5px;padding:8px}button{background:#007f85;color:white;border:0;cursor:pointer}button.secondary{background:#e6eef3;color:#17324d}button:disabled{opacity:.5}input,textarea{background:white;color:#17324d}main{display:grid;grid-template-columns:260px 1fr;gap:18px;padding:20px 28px;max-width:1500px;margin:auto}aside,.card{background:white;border-radius:8px;padding:18px;border:1px solid #d5e0e8}aside{align-self:start;position:sticky;top:10px;max-height:86vh;overflow:auto}.card{margin-bottom:14px}#list button{display:block;text-align:left;width:100%;margin:5px 0;background:#edf3f6;color:#17324d;font-size:12px}#list button.active{background:#007f85;color:white}#quote{font-size:17px;line-height:1.65;border-left:4px solid #007f85;padding:8px 16px;background:#f3f8fa;white-space:pre-wrap}.muted{font-size:13px;color:#5d7283}.callout{background:#fff5e8;border-left:4px solid #c87928;padding:10px 15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.grid label{display:flex;flex-direction:column;gap:5px}textarea{width:100%;min-height:80px}.reasons{display:grid;grid-template-columns:1fr 1fr;gap:7px}.reason{padding:8px;background:#f3f7fa;border:1px solid #dbe5eb;border-radius:5px;font-size:13px}.reason small{display:block;color:#5b6c7b;margin-left:24px}.reason input{margin-right:8px}details{margin:8px 0}summary{cursor:pointer;font-weight:600}#message{padding:8px 28px;font-size:13px;min-height:35px;background:#dceeed}#counter{font-size:13px}kbd{background:#e5edf3;padding:1px 5px}.actions{display:flex;gap:10px;flex-wrap:wrap}.warning{color:#9c4e11}footer{padding:10px 28px 30px;font-size:12px;color:#596e7e}@media(max-width:850px){main{grid-template-columns:1fr;padding:12px}aside{position:static;max-height:240px}.reasons,.grid{grid-template-columns:1fr}}
</style></head><body>
<header><h1>Review the LLM's explanations</h1><div>Read each explanation, check proposed reasons, and record evidence and criterion fit.</div></header>
<div class="bar"><input id="search" placeholder="Search ID or explanation" aria-label="Search"><select id="criterion"><option value="">All criteria</option></select><select id="filter"><option value="">All records</option><option value="todo">Labels to review</option><option value="reviewed">Labels reviewed</option><option value="unresolved">No proposed reason</option></select><button id="export">Export review CSV</button><label class="muted">Resume from CSV <input type="file" id="import" accept=".csv"></label></div>
<div id="message">This page works offline. Export your review CSV to keep a durable copy. No judgments are prefilled.</div>
<main><aside><div id="counter"></div><div class="actions"><button class="secondary" id="prevPage">Previous</button><button class="secondary" id="nextPage">Next</button></div><div id="list"></div></aside><section>
<div class="card"><h2 id="title"></h2><div id="quote"></div><p id="ruleEvidence" class="muted"></p><details open><summary>Original requirement and quality criterion</summary><p id="requirement"></p><p id="critDef"></p><p class="muted" id="context"></p><p class="muted">Source PDF: inputs/Requirements_Documentation_Point_Mass.pdf, page 2. Review the original PDF when layout or Figure 1 matters. Exact original model input is unavailable.</p></details><div id="notes" class="callout"></div></div>
<div class="card"><h2>1. Which reasons are actually expressed?</h2><p class="muted">Select every reason supported by the explanation. Suggestions are editable. Change config/reason_codebook.json and rerun if a new category is needed.</p><div class="reasons" id="reasons"></div><p><label>Label review status <select id="labelStatus"><option value="proposed">Proposed / not reviewed</option><option value="reviewed">Reviewed by me</option><option value="needs_revision">Needs revision</option></select></label></p></div>
<div class="card"><h2>2. Assess the evidence and the assigned criterion</h2><p class="muted">Source status concerns the explanation's claims relative to the provided materials. Criterion fit concerns whether the explanation justifies this criterion. Neither automatically confirms a real requirement defect.</p><div class="grid"><label>Source evidence<select id="sourceStatus"></select></label><label>Criterion fit<select id="alignmentStatus"></select></label><label>Reviewer name<input id="reviewer" placeholder="Your name"></label><label>Evidence location<input id="locator" placeholder="e.g. Point Mass PDF p.2, FR1 Note 1; task p.1 A4"></label></div><p><label>Reason for your judgment / uncertainty<textarea id="assessment"></textarea></label></p><div class="actions"><button id="save">Save this review</button><button class="secondary" id="saveNext">Save and next</button></div><p class="muted">Browser storage is only a convenience. Export CSV, save it in working/, and rerun with <kbd>--reviewed working/annotations_reviewed.csv</kbd>.</p></div>
</section></main><footer>Suggestions were generated by transparent rules in the proposed codebook. No independent human validation is claimed. The original workbook is never edited.</footer>
<script type="application/json" id="data">__DATA__</script>
<script>
'use strict';const data=JSON.parse(document.getElementById('data').textContent);const rows=data.rows;const byId=Object.fromEntries(rows.map(r=>[r.record_id,r]));const refs=Object.fromEntries(data.reference.requirements.map(r=>[r.requirement_id,r]));const crits=Object.fromEntries(data.criteria.map(c=>[c.criterion_id,c]));const fields=['record_id','explanation_sha256','reviewed_reason_ids','label_review_status','source_status','alignment_status','reviewer','reviewed_at','evidence_locator','assessment_note'];const $=id=>document.getElementById(id);let current=null,page=0,filtered=[],dirty=false,overrides={};const storageKey='stselabReview_'+data.hash;
const sourceLabels={pending:'Pending',supported:'Supported',partly_supported:'Partly supported',contradicted:'Contradicted',not_verifiable:'Not verifiable from supplied material'};const alignLabels={pending:'Pending',aligned:'Aligned',partly_aligned:'Partly aligned',misaligned:'Misaligned',not_judgable:'Not judgable from supplied material'};
function option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}
for(const c of data.criteria)option($('criterion'),c.criterion_id,c.criterion_id+' '+c.name);for(const [k,v] of Object.entries(sourceLabels))option($('sourceStatus'),k,v);for(const [k,v] of Object.entries(alignLabels))option($('alignmentStatus'),k,v);
try{overrides=JSON.parse(localStorage.getItem(storageKey)||'{}');for(const [id,v] of Object.entries(overrides))if(byId[id]&&byId[id].explanation_sha256===v.explanation_sha256)Object.assign(byId[id],v)}catch(e){overrides={}}
function msg(text,bad=false){$('message').textContent=text;$('message').style.background=bad?'#ffe8d7':'#dceeed'}
function codes(s){return (s||'').split(';').filter(Boolean)}
function updateList(){const s=$('search').value.toLowerCase(),c=$('criterion').value,f=$('filter').value;filtered=rows.filter(r=>(!c||r.criterion_id===c)&&(!s||(r.record_id+' '+r.explanation).toLowerCase().includes(s))&&(!f||(f==='todo'&&r.label_review_status!=='reviewed')||(f==='reviewed'&&r.label_review_status==='reviewed')||(f==='unresolved'&&!r.proposed_reason_ids)));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/50)-1));$('counter').textContent=filtered.length+' matching · '+rows.filter(r=>r.label_review_status==='reviewed').length+'/'+rows.length+' labels reviewed';$('list').replaceChildren();for(const r of filtered.slice(page*50,page*50+50)){const b=document.createElement('button');b.textContent=(r.label_review_status==='reviewed'?'✓ ':'')+r.record_id;b.className=current&&current.record_id===r.record_id?'active':'';b.onclick=()=>{if(dirty&&!confirm('Discard unsaved edits on this record?'))return;show(r)};$('list').append(b)}$('prevPage').disabled=page===0;$('nextPage').disabled=(page+1)*50>=filtered.length}
function show(r){current=r;dirty=false;$('title').textContent=r.record_id;$('quote').textContent=r.explanation;$('requirement').textContent=r.requirement_id+': '+refs[r.requirement_id].text;$('critDef').textContent=r.criterion_id+' — '+crits[r.criterion_id].name+': '+crits[r.criterion_id].definition;$('context').textContent='Project context: '+data.reference.project_context+' ConOps: '+data.reference.conops.join(' ');$('notes').textContent=r.review_notes||'Read the criterion definition and source carefully; record any uncertainty.';$('ruleEvidence').textContent='Proposed codes: '+(r.proposed_reason_ids||'UNRESOLVED')+'. Matches are only candidate evidence; read the entire explanation.';
const selected=new Set(codes(r.reviewed_at?r.reviewed_reason_ids:r.effective_reason_ids));$('reasons').replaceChildren();for(const reason of data.codebook){const label=document.createElement('label');label.className='reason';const input=document.createElement('input');input.type='checkbox';input.value=reason.reason_id;input.checked=selected.has(reason.reason_id);input.onchange=()=>dirty=true;label.append(input,document.createTextNode(reason.reason_id+' '+reason.label));const small=document.createElement('small');small.textContent=reason.definition;label.append(small);label.title='Include: '+reason.inclusion+' Exclude: '+reason.exclusion;$('reasons').append(label)}$('labelStatus').value=r.label_review_status;$('sourceStatus').value=r.source_status;$('alignmentStatus').value=r.alignment_status;$('reviewer').value=r.reviewer||sessionStorage.getItem('stselabReviewer')||'';$('locator').value=r.evidence_locator;$('assessment').value=r.assessment_note;updateList()}
function save(){if(!current)return false;const selected=[...$('reasons').querySelectorAll('input:checked')].map(x=>x.value).sort();const status=$('labelStatus').value,source=$('sourceStatus').value,alignment=$('alignmentStatus').value,reviewer=$('reviewer').value.trim(),locator=$('locator').value.trim(),note=$('assessment').value.trim();if(status==='reviewed'&&!selected.length){msg('A reviewed explanation needs at least one defined reason. Add a new code if necessary.',true);return false}if((status==='reviewed'||source!=='pending'||alignment!=='pending')&&!reviewer){msg('Enter a reviewer name.',true);return false}if((source!=='pending'||alignment!=='pending')&&(!locator||!note)){msg('Evidence judgments need a source location and an explanation.',true);return false}const v={record_id:current.record_id,explanation_sha256:current.explanation_sha256,reviewed_reason_ids:selected.join(';'),label_review_status:status,source_status:source,alignment_status:alignment,reviewer,reviewed_at:new Date().toISOString(),evidence_locator:locator,assessment_note:note};Object.assign(current,v);overrides[current.record_id]=v;let persisted=true;try{localStorage.setItem(storageKey,JSON.stringify(overrides));sessionStorage.setItem('stselabReviewer',reviewer)}catch(e){persisted=false}dirty=false;updateList();msg(persisted?'Saved in this browser. Export the CSV to keep and analyze your review.':'Browser storage is unavailable. Export the CSV now to keep this review.',!persisted);return true}
function csvCell(s){return '"'+String(s??'').replaceAll('"','""')+'"'}
$('save').onclick=save;$('saveNext').onclick=()=>{const index=filtered.findIndex(r=>r.record_id===current.record_id);const next=filtered[index+1];if(save()&&next)show(next)};$('export').onclick=()=>{if(dirty&&!save())return;const lines=[fields.map(csvCell).join(',')];for(const r of rows)lines.push(fields.map(k=>csvCell(r[k])).join(','));const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='annotations_reviewed.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);msg('CSV exported. Save it in working/ and rerun the analysis with --reviewed.')};
function parseCSV(text){text=text.replace(/^\ufeff/,'');const records=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(field);field=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x!==''))records.push(row);row=[];field=''}else field+=ch}if(field||row.length){row.push(field);records.push(row)}if(quoted)throw new Error('Unclosed CSV quote');const header=records.shift()||[];return records.map(r=>Object.fromEntries(header.map((h,i)=>[h,r[i]??''])))}
$('import').onchange=async()=>{try{const file=$('import').files[0];if(!file)return;const incoming=parseCSV(await file.text());const updates={};for(const r of incoming){if(!byId[r.record_id]||byId[r.record_id].explanation_sha256!==r.explanation_sha256)throw new Error('CSV record/hash mismatch: '+r.record_id);for(const f of fields)if(!(f in r))throw new Error('Missing CSV field '+f);updates[r.record_id]=Object.fromEntries(fields.map(f=>[f,r[f]]))}for(const [id,v] of Object.entries(updates)){Object.assign(byId[id],v);overrides[id]=v}try{localStorage.setItem(storageKey,JSON.stringify(overrides))}catch(e){}dirty=false;updateList();if(current)show(current);msg('Imported '+incoming.length+' rows. The Python pipeline performs full validation when you rerun.')}catch(e){msg(e.message,true)}};
for(const id of ['search','criterion','filter'])$(id).addEventListener('input',()=>{page=0;updateList()});for(const id of ['labelStatus','sourceStatus','alignmentStatus','reviewer','locator','assessment'])$(id).addEventListener('input',()=>dirty=true);$('prevPage').onclick=()=>{page--;updateList()};$('nextPage').onclick=()=>{page++;updateList()};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});updateList();if(rows.length)show(rows[0]);
</script></body></html>'''
